# Test the theory: if any neighbor changes, does the cell change?
print("Testing neighborhood propagation theory:")

for demo_idx, demo in enumerate(demos):
    inp = demo['input']
    outp = demo['output']
    h, w = len(inp), len(inp[0])

    # Find all cells that change
    changed_cells = set()
    for r in range(h):
        for c in range(w):
            if inp[r][c] != outp[r][c]:
                changed_cells.add((r, c))

    # For each changed cell, check if any neighbor also changed
    all_neighbors_changed = True
    for (r, c) in changed_cells:
        has_changed_neighbor = False
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) in changed_cells:
                    has_changed_neighbor = True
                    break
        if not has_changed_neighbor:
            all_neighbors_changed = False
            sample = (r, c)
            print(f"Demo {demo_idx}: Changed cell {sample} has NO changed neighbors")
            print(f"  neighbors: ", end="")
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    print(f"({nr},{nc})={inp[nr][c]}->{outp[nr][nc]} ", end="")
            print()
            break

    # Also check if all unchanged cells have no changed neighbors
    unchanged_cells = set()
    for r in range(h):
        for c in range(w):
            if inp[r][c] == outp[r][c]:
                unchanged_cells.add((r, c))

    for (r, c) in list(unchanged_cells)[:5]:  # Check first 5
        has_changed_neighbor = False
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) in changed_cells:
                    has_changed_neighbor = True
                    break
        if has_changed_neighbor:
            print(f"Demo {demo_idx}: Unchanged cell {sample} has a CHANGED neighbor (violates theory)")
            print(f"  neighbors: ", end="")
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    print(f"({nr},{nc})={inp[nr][c]}->{outp[nr][nc]} ", end="")
            print()
            break

    if all_neighbors_changed:
        print(f"Demo {demo_idx}: ALL changed cells have AT LEAST ONE changed neighbor")

