                    if curr[0] == 0 or curr[0] == h-1 or curr[1] == 0 or curr[1] == w-1:
                        component_reaches_boundary = True

                    for d in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr[0]+d[0], curr[1]+d[1]
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc]==value:
                            if (nr, nc) not in visited:
                                queue.append((nr, nc))

                if component_reaches_boundary:
                    return True
    return False

def predict_source(grid):
    """Source rule:
    - First check if any non-bg value has a component that does NOT touch boundary (trapped)
    - If trapped exists: among values whose ALL components are trapped, pick max comp; tie: max cells
    - Else: among ALL non-bg values, pick max comp; tie: max cells
    """
    h, w = len(grid), len(grid[0])
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1

    background = max(counts, key=counts.get)

    # Check trapped candidates
    trapped = []
    for v in counts:
        if v != background:
            touches = all_components_touch_boundary(grid, v)
            if not touches:
                comp = careful_count_components(grid, v)
                cells = counts[v]
                trapped.append((v, comp, cells))

    if trapped:
        trapped.sort(key=lambda x: (-x[1], -x[2]))
        return trapped[0][0]

    # Fallback: most components overall
    best = None
    max_c = -1
    for v in counts:
        if v == background or v in [x[0] for x in trapped]:
            continue
        c = careful_count_components(grid, v)
        if c > max_c or (c == max_c and (best is None or counts[v] > counts[best])):
            max_c = c
            best = v
    return best

# Test source rule
print("Source rule (trapped check first, then most comp):")
all_ok = True
for demo_idx, demo in enumerate(demos):
    inp = demo['input']

    actual_source = None
    for r in range(len(inp)):
        for c in range(len(inp[0])):
            if inp[r][c] != demo['output'][r][c]:
                v = inp[r][c]
                if actual_source is None:
                    actual_source = v

    pred_src = predict_source(inp)
    correct = (actual_source == pred_src)
    if not correct:
        all_ok = False
        print(f"Demo {demo_idx}: FAIL - actual={actual_source}, predicted={pred_src}")
    # else:
    #     print(f"Demo {demo_idx}: OK - {actual_source}")

if all_ok:
    print("All demos pass for source rule!")

